#!/usr/bin/env bash
# 第二批重交：第一次提交的 8 个任务在 CR 上卡在 processing 超过 30 分钟
cd "$(dirname "$0")/.."
S7=assets/sheets/seven-sheet-v2-0.png; ENF=assets/sheets/enf-sheet-v1-0.png; PH=assets/prop-headphones-0.png
O=assets; L=work/logs/wave2b.log
STY="Same art style as the reference: flat 2D cel-shaded 1980s OVA anime, clean ink linework, subtle halftone and film grain."
BG="plain warm off-white background with subtle halftone. No panels, no text."
SEV="the same girl 'Seven' from the reference sheet: same face, silver-grey eyes, black asymmetric bob with straight bangs, ONE orange hair streak on the right side of her face; cream retro headphones with an orange stripe and a short black coiled cord; oversized olive-green MA-1 jacket with orange lining, ONE round '07' patch on her LEFT upper sleeve only, small silver safety pin on her LEFT chest; black turtleneck, dark grey shorts, black tights, chunky white sneakers."
EN="the same 'Enforcer' android from the reference sheet: tall slender elegant porcelain-white ceramic body, thin black seam lines at the joints, long white armor coat-tail panels from waist to knees, white heeled armored boots, smooth white helmet with round ear discs and one glossy black visor covering the face, no features."
ENH="$EN She now wears the girl's headphones from the other reference image (cream white, orange stripe on each cup, short black coiled cord) over her helmet, on top of the ear discs."
img(){ local n=$1 sz=$2; shift 2; bin/cr-image --model gpt-image-2.5-flare --size $sz --out $O --name $n "$@" >> $L 2>&1; }
F=1024x1536; W=1536x1024
img enf-a1-front-r $F --image $ENF --prompt "$STY This is $EN Full body, the ENTIRE figure from the top of the helmet to the boots fully inside the frame with empty margin above the head, front view, standing straight and still, arms at sides, visor completely black. Only one figure. $BG" &
img enf-b1-visor-r $W --image $ENF --image $PH --prompt "$STY Image 1 is the Enforcer, image 2 is the headphones. Draw $ENH Close-up of the head and shoulders, three-quarter view. For the first time, a simple glowing soft orange audio waveform line is displayed across the middle of the black visor, like a heartbeat of music. Only one figure. $BG" &
img enf-b2-side-r $F --image $ENF --image $PH --prompt "$STY Image 1 is the Enforcer, image 2 is the headphones. Draw $ENH Full body side view facing right, whole figure inside the frame, standing gracefully, visor black with a faint orange waveform line. Only one figure. $BG" &
img enf-b3-back-r $F --image $ENF --image $PH --prompt "$STY Image 1 is the Enforcer, image 2 is the headphones. Draw $ENH Full body seen from directly BEHIND, whole figure inside the frame, standing straight; the headphone band visible over the back of the white helmet. Only one figure. $BG" &
img pair-height-r $W --image $S7 --image $ENF --prompt "$STY Image 1 is the girl Seven, image 2 is the Enforcer android. Height comparison model sheet: both standing side by side, full body, side view, both facing right, Seven on the left, the Enforcer on the right. The Enforcer is noticeably taller: Seven's head reaches the Enforcer's chest. Seven is $SEV The Enforcer is $EN Exactly two figures. $BG" &
img seven-a7-surprise-r $W --image $S7 --image assets/prop-card-blank-0.png --prompt "$STY Image 1 is the girl, image 2 is the card. Draw $SEV Close-up head and shoulders, she holds the blank cream punch card from image 2 (no holes) up in front of her chest with both hands and looks down at it, eyes widened slightly in quiet surprise, lips slightly parted, restrained, not cartoonish. Only one figure. $BG" &
SC="Use the reference only for the art style; flat 2D cel-shaded 1980s OVA anime background art, clean ink linework, subtle halftone, film grain. No people, no readable text, no logos."
img white-2-side-r $W --image assets/white-1-door-0.png --prompt "$SC Same location as the reference: the vast empty pure white space with faint cool grey horizon and soft floor reflection, and the same tall door made of glowing white and pale cyan particles. Now seen from the side: the camera is rotated 90 degrees, the particle door stands on the right third of the frame seen at an angle, a long empty stretch of white floor on the left where two figures could face each other." &
img roof-2-wide-r $W --image assets/roof-1-sunrise-0.png --prompt "$SC Same location as the reference: the same flat rooftop of the enormous monolithic building above the sea of clouds, same rising sun and sky colors. Now a very wide side view: the long flat rooftop runs horizontally across the frame toward the horizon and the sun, tiny scale, lots of open sky." &
wait
